// Run once:  npm run setup:bot
// Sets the text people see BEFORE pressing START (screenshot 1).
// Telegram adds the "What can this bot do?" title itself.
import { Bot } from 'grammy';
import 'dotenv/config';

if (!process.env.BOT_TOKEN) throw new Error('BOT_TOKEN is missing in .env');
const bot = new Bot(process.env.BOT_TOKEN);

await bot.api.setMyDescription(
  '🚘 Getachew Fikadu Jirata\n\n' +
    'Baga gara Bot keenyaa dhuftan.\n\n' +
    'ወደ ቦታችን እንኳን በደህና መጡ።\n\n' +
    'Welcome to our bot.'
);
await bot.api.setMyShortDescription('🚘 Getachew Fikadu Jirata');
await bot.api.setMyCommands([{ command: 'start', description: 'Start' }]);
console.log('Bot description set. Set the round logo in @BotFather -> /setuserpic');
